@extends('layouts.app') @section('title','Transfer to Remnant') @section('content')@php $catalog=$products->map(fn($p)=>['id'=>$p->id,'stock'=>(float)$p->balances->where('inventory_type','main')->sum('quantity'),'cost'=>(float)$p->average_cost,'units'=>$p->productUnits->map(fn($u)=>['id'=>$u->unit_id,'label'=>$u->unit->name.' ('.$u->unit->symbol.')','rate'=>(float)$u->conversion_rate,'normal'=>(float)($p->main_selling_price * $u->conversion_rate),'remnant'=>(float)($p->remnant_selling_price * $u->conversion_rate)])->values()])->values(); @endphp<div class="mx-auto max-w-4xl"><a class="text-sm text-slate-500" href="{{ route('remnants.index') }}">← Remnants</a><h1 class="mt-2 font-serif text-3xl text-ink">Transfer main stock to remnant</h1><p class="mb-6 text-sm text-slate-500">This creates one transfer-out and one transfer-in. Combined physical stock remains unchanged.</p><form method="post" action="{{ route('remnants.transfer.store') }}" class="card p-6" x-data='transfer(@json($catalog))'>@csrf<div class="grid gap-5 md:grid-cols-2"><div class="md:col-span-2"><label>Product</label><select class="w-full" name="product_id" x-model.number="product" @change="productChanged()" required x-init="initTomSelect($el)"><option value="">Select a product</option>@foreach($products as $p)<option value="{{ $p->id }}">{{ $p->name }} · {{ $p->sku }}</option>@endforeach</select></div><div><label>Store</label><select class="w-full" name="store_id">@foreach($stores as $s)<option value="{{ $s->id }}">{{ $s->name }}</option>@endforeach</select></div><div><label>Available main stock (base)</label><div class="rounded-xl bg-slate-50 px-3 py-2.5 font-semibold" x-text="selected?selected.stock.toFixed(3):'—'"></div></div><div><label>Transfer unit</label><select class="w-full" name="unit_id" x-model.number="unit" required><template x-for="u in units"><option :value="u.id" x-text="u.label"></option></template></select></div><div><label>Quantity</label><input class="w-full" type="number" min="0.001" step="0.001" name="quantity" x-model.number="qty" required></div><div><label>Base equivalent</label><div class="rounded-xl bg-teal/5 px-3 py-2.5 font-semibold text-teal" x-text="baseLabel()"></div></div><div><label>Average cost / base</label><div class="rounded-xl bg-slate-50 px-3 py-2.5" x-text="costLabel()"></div></div><div><label>New remnant selling price</label><input class="w-full" type="number" min="0" step="0.01" name="remnant_price" x-model.number="price" required></div><div><label>Discount %</label><input class="w-full" type="number" min="0" max="100" step="0.01" name="discount_percent"></div><div><label>Reason</label><select class="w-full" name="reason"><option>Small roll remainder</option><option>Cut piece</option><option>Clearance</option><option>Damaged edge</option><option>Other</option></select></div><div class="md:col-span-2"><label>Notes</label><textarea class="w-full" name="notes"></textarea></div></div><div class="mt-6 flex justify-end"><button class="btn bg-amber-500 text-white">Create remnant lot</button></div></form></div>@push('scripts')<script>function transfer(c){return{catalog:c,product:'',unit:'',qty:0,price:0,get selected(){return this.catalog.find(p=>p.id==this.product)},get units(){return this.selected?.units||[]},get currentUnit(){return this.units.find(u=>u.id==this.unit)},get base(){return (Number(this.qty)||0)*(this.currentUnit?.rate||0)},productChanged(){this.unit=this.units[0]?this.units[0].id:''},baseLabel(){return this.base.toFixed(3)+' base units'},costLabel(){return this.selected?'Rs. '+this.selected.cost.toFixed(4):'—'}}}</script>@endpush @endsection
